package com.example.vt.config;

import java.util.concurrent.Executor;
import java.util.concurrent.Executors;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableAsync;

/**
 * 虚拟线程执行器配置。
 *
 * 核心认知：虚拟线程由 JVM 调度，不需要像平台线程那样「先建一个固定大小的池再去复用」。
 * 每个任务直接由一个虚拟线程承载，用完即弃，调度成本极低。
 *
 * 用法：在异步方法上写 @Async("virtualThreadExecutor") 即可让它在虚拟线程上运行，
 * 而不是默认的平台线程池。显式命名能避免误伤其它本就想用平台线程池的 @Async 任务。
 */
@EnableAsync
@Configuration
public class VirtualThreadConfig {

    /**
     * 返回每任务虚拟线程执行器。
     *
     * Executors.newVirtualThreadPerTaskExecutor() 不持有线程池，每次 submit 新建一个
     * 虚拟线程。这正是虚拟线程的正确用法——不要把它再包进 newFixedThreadPool 去「复用」，
     * 那会把轻量调度重新变成重量级排队。
     */
    @Bean("virtualThreadExecutor")
    public Executor virtualThreadExecutor() {
        return Executors.newVirtualThreadPerTaskExecutor();
    }
}

package com.example.vt.service;

import com.example.vt.model.FetchResult;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executor;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;

/**
 * 并发抓取服务：一次请求要并发调用 N 个独立下游（批量查外部 API、并行抓取等）。
 *
 * 用虚拟线程取代线程池：N 个任务就起 N 个虚拟线程，JVM 把它们复用到少量 carrier 线程上，
 * 谁在等 IO 谁就挂起，不占 carrier。代码可以用最朴素的「提交 -> get 结果」阻塞写法，
 * 不必为并发去写回调或响应式地狱。
 *
 * 但虚拟线程便宜 ≠ 下游扛得住：所以仍然保留 Semaphore 闸门和每任务超时两道背压。
 */
@Service
public class ConcurrentFetcher {

    private final Executor vtExecutor;
    /** 下游并发上限：即使虚拟线程免费，也别把依赖打爆。 */
    private final Semaphore downstreamGate = new Semaphore(200);
    private final long callTimeoutMs = 3_000;

    public ConcurrentFetcher(@Qualifier("virtualThreadExecutor") Executor vtExecutor) {
        this.vtExecutor = vtExecutor;
    }

    /**
     * 并发拉取一批地址。虚拟线程执行器随用随建，用 try-with-resources 关闭。
     * 关闭执行器会让所有已提交任务正常结束，这是虚拟线程推荐的生命周期写法。
     */
    @Async("virtualThreadExecutor")
    public List<FetchResult> fetchAll(List<String> urls) throws InterruptedException {
        var executor = Executors.newVirtualThreadPerTaskExecutor();
        List<Future<FetchResult>> futures = new ArrayList<>();
        List<FetchResult> results = new ArrayList<>();

        try (executor) {
            for (String url : urls) {
                // 背压闸门：拿不到许可说明下游已饱和，快速失败而不是无限堆积。
                if (!downstreamGate.tryAcquire(callTimeoutMs, TimeUnit.MILLISECONDS)) {
                    throw new BackpressureException("下游饱和，并发超过 " + downstreamGate.availablePermits());
                }
                Future<FetchResult> f = executor.submit(() -> callDownstream(url));
                futures.add(f);
            }

            for (Future<FetchResult> f : futures) {
                try {
                    // 每个任务单独超时：一个慢下游只拖垮自己，不影响整批。
                    results.add(f.get(callTimeoutMs, TimeUnit.MILLISECONDS));
                } catch (TimeoutException e) {
                    f.cancel(true);
                    results.add(FetchResult.timeout());
                } finally {
                    downstreamGate.release();
                }
            }
        }
        return results;
    }

    private FetchResult callDownstream(String url) {
        // 真实实现里这里是带连接/读超时的 HTTP 客户端调用。
        return FetchResult.ok(url);
    }

    public static class BackpressureException extends RuntimeException {
        public BackpressureException(String msg) {
            super(msg);
        }
    }
}

import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

/**
 * 模拟接口：本机起一个假下游，每个请求阻塞 80ms（模拟真实网络等待）。
 * 下游自己也用虚拟线程，保证瓶颈在客户端的承载方式上，而不是下游先被打满。
 */
public class Main {

    // N 刻意不取很大：并发 TCP 连接本身就是资源，几千条连接会把连接层压成瓶颈，
    // 那时测出来的是「谁更会冲垮自己」，不是「谁更能并发等 IO」。
    static final int N = 150;
    static final int IO_MS = 200;

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/downstream", ex -> {
            sleep(IO_MS);
            byte[] body = "ok".getBytes();
            ex.sendResponseHeaders(200, body.length);
            ex.getResponseBody().write(body);
            ex.close();
        });
        server.setExecutor(Executors.newVirtualThreadPerTaskExecutor());
        server.start();
        String url = "http://127.0.0.1:" + server.getAddress().getPort() + "/downstream";

        try {
            run("虚拟线程", url, Executors.newVirtualThreadPerTaskExecutor());
            run("平台线程池(50)", url, Executors.newFixedThreadPool(50));
        } finally {
            server.stop(0);
        }
        System.out.println("java.version=" + System.getProperty("java.version"));
    }

    static void run(String label, String url, ExecutorService ex) throws Exception {
        var client = HttpClient.newHttpClient();
        long t0 = System.nanoTime();
        int ok = 0;
        try (ex) {
            List<Future<Integer>> futures = new ArrayList<>();
            for (int i = 0; i < N; i++) futures.add(ex.submit(() -> call(client, url)));
            for (Future<Integer> f : futures) ok += f.get();
        }
        long ms = (System.nanoTime() - t0) / 1_000_000;
        System.out.printf("%-16s %d 次调用 -> %4dms（成功 %d）%n", label, N, ms, ok);
    }

    static int call(HttpClient client, String url) {
        try {
            var req = HttpRequest.newBuilder(URI.create(url))
                    .timeout(Duration.ofSeconds(10)).GET().build();
            return client.send(req, HttpResponse.BodyHandlers.ofString()).statusCode() == 200 ? 1 : 0;
        } catch (Exception e) {
            return 0;
        }
    }

    static void sleep(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

package com.example.vt.concurrent;

import java.util.concurrent.locks.ReentrantLock;

/**
 * 防 pinning：虚拟线程遇到 synchronized 临界区时无法「卸载」到 carrier 线程，
 * 于是 carrier 被这个虚拟线程长期占住——相当于把百万级并发退化回平台线程池。
 *
 * 对比两种写法：synchronized 会 pinning，ReentrantLock 不会。
 */
public class PinningSafe {

    // ❌ 反例：synchronized 在虚拟线程热路径上会造成 pinning，抵消虚拟线程收益。
    private final Object badLock = new Object();

    public void bad(String key) {
        synchronized (badLock) {
            doWork(key);
        }
    }

    // ✅ 正例：用 ReentrantLock 替 synchronized，虚拟线程可正常卸载。
    private final ReentrantLock lock = new ReentrantLock();

    public void good(String key) {
        lock.lock();
        try {
            doWork(key);
        } finally {
            lock.unlock();
        }
    }

    // ✅ 进阶：用可中断锁。虚拟线程支持中断，lockInterruptibly 让取消信号
    // 能及时打断正在等待锁的虚拟线程，避免任务无法停止。
    public void cancellable(String key) throws InterruptedException {
        lock.lockInterruptibly();
        try {
            doWork(key);
        } finally {
            lock.unlock();
        }
    }

    private void doWork(String key) {
        // 业务逻辑
    }
}

package com.example.vt.concurrent;

import java.lang.ThreadLocal;

/**
 * 上下文传递：ThreadLocal 是 per-thread 存储。在平台线程时代靠「线程复用」摊薄成本，
 * 但虚拟线程是短命的、可能百万级并存——每个虚拟线程各持一份 ThreadLocal 会被放大成
 * 百万份，且线程不复用让「set 一次用全程」的假设失效，极易串号或泄漏。
 *
 * 结论：虚拟线程场景下迁移到 ScopedValue（JDK 21 preview / JDK 22+ 转正），
 * 它随调用栈绑定、作用域结束即回收，没有 per-thread 存储。
 */
public class ContextHolder {

    // ❌ 海量虚拟线程下会内存放大，且必须记得 remove。
    private static final ThreadLocal<RequestContext> CTX = new ThreadLocal<>();

    public void handleOld(RequestContext ctx) {
        CTX.set(ctx);
        try {
            business();
        } finally {
            CTX.remove(); // 不 remove 就会泄漏 / 串号
        }
    }

    // ✅ 升级方案：ScopedValue 随 run 的作用域绑定，自动回收，无 per-thread 存储。
    // private static final ScopedValue<RequestContext> CTX = ScopedValue.newInstance();
    // public void handleNew(RequestContext ctx) {
    //     ScopedValue.where(CTX, ctx).run(this::business);
    // }

    private void business() {
        // 业务逻辑
    }

    public static class RequestContext {
    }
}

import java.util.concurrent.*;

/**
 * ThreadLocal 放大：虚拟线程便宜，per-thread 存储不便宜。
 * 平台线程时代靠「线程复用」摊薄 ThreadLocal 的成本；虚拟线程不复用，
 * 5 万个同时在跑的任务就是 5 万份各自独立的存储。
 *
 * 为什么这一组不跑 pinning：把 carrier 线程全部 pin 住之后，连「唤醒等待锁的
 * 虚拟线程」都排不上 carrier —— 实测直接饿死，测出来是死锁，不是 pinning。
 * 那种写法只能用代码对照说明，不能拿一个会挂死的实验糊弄人。
 */
public class Main {

    static final ThreadLocal<byte[]> CTX = new ThreadLocal<>();

    public static void main(String[] args) throws Exception {
        int n = 50_000;
        long base = used();
        CountDownLatch started = new CountDownLatch(n);
        CountDownLatch release = new CountDownLatch(1);

        try (var ex = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < n; i++) {
                ex.submit(() -> {
                    CTX.set(new byte[512]);     // 每个虚拟线程各持一份
                    started.countDown();
                    release.await();
                    return null;
                });
            }
            started.await();                    // 等 n 个线程都起来、都还持着一份
            long peak = used();
            release.countDown();
            System.out.printf("%d 个虚拟线程各持一份 ThreadLocal(512B) -> 常驻堆增加 ~%d MB%n",
                    n, (peak - base) / 1024 / 1024);
            System.out.printf("单份 512B，理论下限 %.1f MB —— 多出来的是每个虚拟线程自己的栈与 ThreadLocalMap 开销%n",
                    n * 512.0 / 1024 / 1024);
        }
        System.out.println("java.version=" + System.getProperty("java.version"));
    }

    static long used() {
        System.gc();
        try {
            Thread.sleep(200);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        Runtime rt = Runtime.getRuntime();
        return rt.totalMemory() - rt.freeMemory();
    }
}

package com.example.vt.concurrent;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * 背压闸门：虚拟线程便宜，下游不便宜。
 *
 * 虚拟线程让「起一个任务」几乎免费，于是并发量不再被本机的线程数约束 ——
 * 约束转移到下游：一次扇出一万个请求，被打爆的是依赖方，然后是整条链路。
 * 所以并发上限与单任务超时这两道闸门必须显式存在，且与任务承载方式解耦：
 * 闸门是业务约束，不是线程池参数。
 */
public final class DownstreamGate {

    private final Semaphore gate;
    private final long callTimeoutMs;
    private final AtomicInteger rejected = new AtomicInteger();

    public DownstreamGate(int maxInFlight, long callTimeoutMs) {
        this.gate = new Semaphore(maxInFlight);
        this.callTimeoutMs = callTimeoutMs;
    }

    /**
     * 跑一批任务：拿不到许可就快速失败，拿到许可就带超时执行，无论如何归还许可。
     * 返回成功任务的结果，失败任务被跳过 —— 一批发出去，允许部分失败。
     */
    public <T> List<T> runAll(List<Callable<T>> tasks) throws InterruptedException {
        ExecutorService ex = Executors.newVirtualThreadPerTaskExecutor();
        List<Future<T>> futures = new ArrayList<>();
        try (ex) {
            for (Callable<T> task : tasks) {
                // 闸门：拿不到许可说明在飞的请求已经到上限，拒绝而不是排队堆积。
                if (!gate.tryAcquire(callTimeoutMs, TimeUnit.MILLISECONDS)) {
                    rejected.incrementAndGet();
                    continue;
                }
                futures.add(ex.submit(() -> {
                    try {
                        return task.call();
                    } finally {
                        gate.release();
                    }
                }));
            }

            List<T> out = new ArrayList<>(futures.size());
            for (Future<T> f : futures) {
                try {
                    // 单任务超时：一个慢点只拖垮自己，不拖垮整批。
                    out.add(f.get(callTimeoutMs, TimeUnit.MILLISECONDS));
                } catch (TimeoutException e) {
                    f.cancel(true);
                } catch (ExecutionException e) {
                    // 单任务失败不影响其它任务，记日志后跳过。
                }
            }
            return out;
        }
    }

    /** 被闸门拒掉的任务数 —— 这是下游已经饱和的直接证据，要上报监控。 */
    public int rejected() {
        return rejected.get();
    }
}

import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * 模拟接口 + 背压闸门：下游侧统计「同时在飞多少个请求」。
 * 不加闸门时峰值并发等于任务数；加了闸门，峰值被压在许可数以内，代价是总耗时长一点。
 * 这个数字就是「下游扛不扛得住」的直接证据 —— sleep 版测不出来。
 */
public class Main {

    static final int N = 400;
    static final int IO_MS = 25;
    static final AtomicInteger IN_FLIGHT = new AtomicInteger();
    static final AtomicInteger PEAK = new AtomicInteger();
    static String url;

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/downstream", ex -> {
            int now = IN_FLIGHT.incrementAndGet();
            PEAK.accumulateAndGet(now, Math::max);
            try {
                sleep(IO_MS);
                byte[] body = "ok".getBytes();
                ex.sendResponseHeaders(200, body.length);
                ex.getResponseBody().write(body);
            } finally {
                IN_FLIGHT.decrementAndGet();
                ex.close();
            }
        });
        server.setExecutor(Executors.newVirtualThreadPerTaskExecutor());
        server.start();
        url = "http://127.0.0.1:" + server.getAddress().getPort() + "/downstream";

        try {
            run("无闸门", -1);
            PEAK.set(0);
            run("闸门=50", 50);
        } finally {
            server.stop(0);
        }
        System.out.println("java.version=" + System.getProperty("java.version"));
    }

    static void run(String label, int maxInFlight) throws Exception {
        Semaphore gate = maxInFlight > 0 ? new Semaphore(maxInFlight) : null;
        var client = HttpClient.newHttpClient();
        long t0 = System.nanoTime();
        int ok = 0;
        try (ExecutorService ex = Executors.newVirtualThreadPerTaskExecutor()) {
            List<Future<Integer>> futures = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                futures.add(ex.submit(() -> {
                    if (gate != null) gate.acquireUninterruptibly();
                    try {
                        return call(client);
                    } finally {
                        if (gate != null) gate.release();
                    }
                }));
            }
            for (Future<Integer> f : futures) ok += f.get();
        }
        long ms = (System.nanoTime() - t0) / 1_000_000;
        System.out.printf("%-10s %d 次调用 -> %4dms（成功 %d，下游峰值并发 %d）%n",
                label, N, ms, ok, PEAK.get());
    }

    static int call(HttpClient client) {
        try {
            var req = HttpRequest.newBuilder(URI.create(url))
                    .timeout(Duration.ofSeconds(10)).GET().build();
            return client.send(req, HttpResponse.BodyHandlers.ofString()).statusCode() == 200 ? 1 : 0;
        } catch (Exception e) {
            return 0;
        }
    }

    static void sleep(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
